import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const c=JSON.parse(fs.readFileSync(path.join(root,'docs/contract.json'),'utf8').replace(/^\uFEFF/,''));
const outputs={
 'dashboard/src/services/contract.generated.js':`// Generated by tools/sync-contract.mjs from docs/contract.json.\nexport const CONTRACT = Object.freeze(${JSON.stringify(c,null,2)});\n`,
 'gateway/include/contract.generated.h':`// Generated by tools/sync-contract.mjs from docs/contract.json.\n#pragma once\nconstexpr int kSchemaVersion=${c.schemaVersion};\nconstexpr int kHeartbeatMs=${c.heartbeatMs};\nconstexpr int kStaleMs=${c.staleMs};\nconstexpr int kCommandTtlMs=${c.commandTtlMs};\nconstexpr int kMovementTimeoutMs=${c.movementTimeoutMs};\nconstexpr int kFutureSkewMs=${c.futureSkewMs};\nconstexpr const char* kTopicPrefix="${c.topicPrefix}";\n`
};
for(const [file,text] of Object.entries(outputs)){const dest=path.join(root,file);if(process.argv.includes('--check')){if(fs.readFileSync(dest,'utf8')!==text)throw Error('Contract drift: '+file);}else fs.writeFileSync(dest,text);}
console.log(process.argv.includes('--check')?'Contract generated files match':'Contract generated files updated');
